DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef(oid) INTO definition FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='network_send_wave'; IF definition IS NULL THEN RAISE EXCEPTION 'Missing network_send_wave'; END IF; IF position('m.removed_at IS NULL' in definition)=0 THEN IF position('m.workspace_id=w.id AND up.status=''active''' in definition)=0 THEN RAISE EXCEPTION 'Recipient predicate changed'; END IF; EXECUTE replace(definition,'m.workspace_id=w.id AND up.status=''active''','m.workspace_id=w.id AND m.removed_at IS NULL AND up.deleted_at IS NULL AND up.status=''active'''); END IF; END $$;
COMMENT ON FUNCTION public.network_send_wave(uuid) IS 'Manual addressed waves exclude removed members and deleted profiles; existing recipient uniqueness and distance stages remain unchanged.';